-- Chemistry final module. Run seed_chem_course.sql first. Safe to run more than once.

do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'chemistry';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 7, $j$Final Assessment: My Chemistry Investigation and Reflection$j$, $j${"prompt": "Create a chemistry investigation report and reflection of at least 700 words. Use a safe home investigation with household materials only, such as dissolving sugar or salt in water at different temperatures, testing how temperature affects how fast a tablet or sugar dissolves, or comparing the density of liquids. You must have adult permission and supervision. Do not use fire, strong cleaners, bleach, ammonia, unknown chemicals or anything that could harm you or others, and never mix household cleaners. If you cannot do an investigation safely, design one and describe the data you would expect. Proverbs 25:2 says, It is the glory of God to conceal a thing: but the honour of kings is to search out a matter.\n\nPart 1: Question and Hypothesis. State your question, background and a testable hypothesis. Identify the independent, dependent and controlled variables.\nPart 2: Safety and Materials. List your materials and at least five safety rules. Name the adult who gave permission and supervised.\nPart 3: Procedure and Data. Describe your steps in order and show a data table with measurements in SI units. Show at least three trials and the average, with correct significant figures.\nPart 4: Analysis. Include at least two calculations, such as density, average, percent difference or percent yield, with your work and units. Describe a graph you would make.\nPart 5: Chemistry Connections. Explain which of these ideas apply: physical or chemical change, particles and states of matter, solutions and solubility, energy, or reaction rate. Use correct vocabulary from the course.\nPart 6: Conclusion. State whether your data support the hypothesis, describe sources of error and explain how you would improve the investigation.\nPart 7: Stewardship and Careers. Explain how you disposed of materials safely and wisely, and describe one chemistry career and one way chemistry can serve people.\nPart 8: Faith and Reflection. Apply at least three Scripture passages from the King James Version to the study of God's creation and to honest science, and write a reflection on what you learned, what you will improve and your goal for the next year.", "rubric": "100 points. Part 1, question and hypothesis: 10 points. Part 2, safety and materials: 10 points. Part 3, procedure and data: 15 points. Part 4, analysis and calculations: 20 points. Part 5, chemistry connections: 15 points. Part 6, conclusion: 10 points. Part 7, stewardship and careers: 5 points. Part 8, faith and reflection: 10 points. Grammar, conventions and accuracy: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Final Assessment: My Chemistry Investigation and Reflection$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 31, $j$Final Exam: Chemistry$j$, $j${"questions": [{"q": "Anything that has mass and takes up space is:", "options": ["Energy", "Matter", "A solution", "A reaction"]}, {"q": "Which is a chemical change?", "options": ["Iron rusting", "Water boiling", "Ice melting", "Breaking glass"]}, {"q": "The number of protons in an atom is its:", "options": ["Valence number", "Charge", "Mass number", "Atomic number"]}, {"q": "Atoms of the same element with different numbers of neutrons are:", "options": ["Isomers", "Isotopes", "Ions", "Compounds"]}, {"q": "Elements in the same group of the periodic table have the same number of:", "options": ["Energy levels", "Valence electrons", "Neutrons", "Protons"]}, {"q": "An ionic bond forms when electrons are:", "options": ["Destroyed", "Created", "Transferred", "Shared equally"]}, {"q": "The molecule that has a bent shape is:", "options": ["Nitrogen gas", "Carbon dioxide", "Methane", "Water"]}, {"q": "The formula for the compound of magnesium and chlorine is:", "options": ["MgCl", "MgCl2", "Mg2Cl", "Mg2Cl2"]}, {"q": "In a balanced equation, the number of atoms of each element is:", "options": ["Greater in the reactants", "Not important", "The same on both sides", "Greater in the products"]}, {"q": "One mole of a substance contains:", "options": ["22.4 particles", "100 particles", "One gram", "6.02 times 10 to the 23rd particles"]}, {"q": "The molar mass of water is about:", "options": ["34.0 grams per mole", "2.0 grams per mole", "18.0 grams per mole", "16.0 grams per mole"]}, {"q": "According to Boyle's law, if the volume of a gas decreases at constant temperature, pressure:", "options": ["Increases", "Stays the same", "Decreases", "Becomes zero"]}, {"q": "A solution has a pH of 3. It is:", "options": ["A metal", "Neutral", "Basic", "Acidic"]}, {"q": "In a redox reaction, the substance that loses electrons is:", "options": ["Neutralized", "Reduced", "Oxidized", "Condensed"]}, {"q": "Psalm 24:1 says, The earth is the LORD'S, and the fulness thereof. This teaches us to practice:", "options": ["Ignoring safety", "Stewardship of creation", "Avoiding science", "Wasting resources"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Chemistry$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,3,1,1,2,3,1,2,3,2,0,3,2,1}'::int[], array[$j$That is the definition of matter.$j$,$j$Rusting forms a new substance.$j$,$j$The atomic number identifies the element.$j$,$j$Isotopes differ in neutrons.$j$,$j$Valence electrons give similar properties.$j$,$j$Ionic bonding involves transfer.$j$,$j$Two lone pairs bend the water molecule.$j$,$j$One 2 plus ion balances two 1 minus ions.$j$,$j$Mass is conserved.$j$,$j$That is Avogadro's number.$j$,$j$2 hydrogen plus 1 oxygen.$j$,$j$Pressure and volume are inversely related.$j$,$j$Below 7 is acidic.$j$,$j$Oxidation is loss of electrons.$j$,$j$Creation belongs to God and we care for it.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Chemistry$j$ on conflict (item_id) do nothing;
end
$seed$;
